import { sql } from 'drizzle-orm';
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Raw bytes (hashes, WebAuthn ids and keys). Drizzle 0.45 has no built-in `bytea`. */
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});

/** UTC instant (DATA-MODEL.md "Conventions"). */
export const instant = () => timestamp({ withTimezone: true });

export const createdAt = () => instant().notNull().defaultNow();

/** Time-ordered primary key, generated by PostgreSQL 18. */
export const primaryId = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);
